<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import AnalysisPanel from './AnalysisPanel.vue'
import RescoreEditor from './RescoreEditor.vue'
import type { AssessmentDraft, Finding, Me, RescoreProposal } from '../types'

const props = defineProps<{ finding: Finding; draft: AssessmentDraft; me: Me; busy: boolean; error: string; notice: string; power: boolean; canApprove: boolean; index: number; loaded: number; previous: boolean; next: boolean }>()
const emit = defineEmits<{ close: []; move: [delta: number]; refresh: []; 'update:draft': [draft: AssessmentDraft]; submit: [advance: boolean]; approve: [requestChanges: boolean, advance: boolean] }>()
const tab = ref('assessment'), editing = ref(false), step = ref(0)
const scorePreview = ref<RescoreProposal | null>(null), reviewConfirmed = ref(false)
const tabs = [['assessment', 'Assessment & review'], ['analysis', 'Analysis'], ['history', 'Evidence & history']]
const latest = computed(() => props.finding.decisions[0])
const canSubmit = computed(() => !props.busy && props.draft.rationale.trim() && (!props.draft.rescoring || props.draft.rescoring.preview_digest))
const showForm = computed(() => props.finding.capabilities.includes('assess') && (editing.value || (!latest.value && !props.canApprove) || ['needs_revalidation', 'changes_requested'].includes(props.finding.lifecycle)))
const steps = computed(() => showForm.value ? ['Evidence', 'Applicability', 'Severity', 'Confirm'] : ['Evidence', 'Assessment', 'Confirm'])
const lastStep = computed(() => steps.value.length - 1)
const decisionReady = computed(() => Boolean(props.draft.rationale.trim()))
const scoreReady = computed(() => !props.draft.rescoring || Boolean(props.draft.rescoring.preview_digest))
const canContinue = computed(() => !props.busy && (!showForm.value || step.value === 0 || (step.value === 1 ? decisionReady.value : scoreReady.value)))
const furthest = ref(0), stageLabel = ref<HTMLElement | null>(null)
watch(step, async () => { await nextTick(); stageLabel.value?.focus(); stageLabel.value?.closest('.review-content')?.scrollTo({ top: 0 }) })
watch(() => props.finding.lifecycle, value => { if (['approved', 'changes_requested'].includes(value)) { step.value = 0; furthest.value = 0 } })
function goStep(value: number) { step.value = value; furthest.value = Math.max(furthest.value, value) }
function revise() { editing.value = true; furthest.value = 1; step.value = 1 }
watch(showForm, value => { if (!value) { step.value = 0; furthest.value = 0 } })
watch(() => props.finding.state_version, () => { reviewConfirmed.value = false })
watch(() => latest.value?.id, () => { editing.value = false; step.value = 0; furthest.value = 0 })
const names: Record<string, string> = { open: 'Needs analysis', ready: 'Ready for approval', approved: 'Approved', needs_revalidation: 'Evidence changed', changes_requested: 'Changes requested', affected: 'Affected', not_affected: 'Not affected', under_investigation: 'Under investigation', fixed: 'Fixed' }
const label = (state: string) => names[state] || state.replaceAll('_', ' ')
const score = (value: number | null) => value === null ? 'Unknown' : value.toFixed(1)
function update(field: 'state' | 'rationale', value: string) { emit('update:draft', { ...props.draft, [field]: value }) }
function useProposal(state: string, rationale: string) { tab.value = 'assessment'; revise(); emit('update:draft', { ...props.draft, state, rationale }) }
watch(() => props.finding.id, () => { tab.value = 'assessment'; editing.value = false })
</script>
<template>
  <div class="overlay review-overlay" @click.self="!busy && emit('close')"><section class="inspector finding-workspace" role="dialog" aria-modal="true" aria-labelledby="finding-title">
    <div class="inspector-header"><div><p class="eyebrow">{{ finding.project }} · Release {{ finding.release }}</p><h1 id="finding-title">{{ finding.identifier }}</h1><p>{{ finding.component }} {{ finding.component_version }} · {{ finding.owner }}</p></div><button aria-label="Close finding" :disabled="busy" @click="emit('close')">×</button></div>
    <div class="review-navigation"><div class="queue-navigation"><button :disabled="busy || !previous" @click="emit('move', -1)">Previous finding</button><span>{{ index >= 0 ? `${index + 1} of ${loaded} loaded` : 'Outside current queue' }}</span><button :disabled="busy || !next" @click="emit('move', 1)">Next finding</button></div><div class="review-tabs" role="tablist" aria-label="Review sections"><button v-for="[key, name] in tabs" :id="`review-tab-${key}`" :key="key" role="tab" :aria-selected="tab === key" :aria-controls="`review-panel-${key}`" :tabindex="tab === key ? 0 : -1" :class="{ current: tab === key }" @click="tab = key!" @keydown.right.prevent="tab = tabs[(tabs.findIndex(item => item[0] === tab) + 1) % tabs.length]![0]!; ($event.target as HTMLElement).parentElement?.querySelector<HTMLElement>(`#review-tab-${tab}`)?.focus()" @keydown.left.prevent="tab = tabs[(tabs.findIndex(item => item[0] === tab) + tabs.length - 1) % tabs.length]![0]!; ($event.target as HTMLElement).parentElement?.querySelector<HTMLElement>(`#review-tab-${tab}`)?.focus()">{{ name }}</button></div></div>
    <div class="inspector-content review-content">
      <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message success" role="status">{{ notice }}</p>
      <div v-show="tab === 'assessment'" id="review-panel-assessment" role="tabpanel" aria-labelledby="review-tab-assessment">
        <nav class="assessment-steps" aria-label="Assessment progress"><button v-for="(name, index) in steps" :key="name" :aria-current="step === index ? 'step' : undefined" :disabled="busy || index > furthest" @click="goStep(index)"><span>{{ index < step ? '✓' : index + 1 }}</span>{{ name }}</button></nav>
        <div class="guided-stage" :data-step="step">
        <p ref="stageLabel" tabindex="-1" class="eyebrow">Step {{ step + 1 }} of {{ steps.length }} · {{ showForm ? 'Assess this occurrence' : canApprove ? 'Independent review' : 'Recorded assessment' }}</p>
        <div class="review-grid">
          <div v-show="step === 0" class="evidence-column">
            <div class="review-summary"><span class="badge" :class="finding.lifecycle">{{ label(finding.lifecycle) }}</span><div><span class="hint">Original Base severity</span><strong class="score" :class="{ high: (finding.original_score || 0) >= 7 }">{{ score(finding.original_score) }}</strong></div><div v-if="finding.adopted_rescoring"><span class="hint">Approved contextual</span><strong>{{ score(finding.effective_score) }}</strong></div></div>
            <section class="review-section"><h2>What needs review</h2><p class="finding-description">{{ finding.description || 'No advisory description supplied. Review the source evidence.' }}</p><p v-if="finding.lifecycle === 'needs_revalidation'" class="warning">Evidence changed since the last decision. Review the changes and submit a new assessment.</p><p v-if="finding.conflicting_scores" class="warning">Sources disagree on the original score. Review the Base assertions before rescoring or exporting.</p><p v-if="finding.stale_evidence" class="warning">Source evidence is older than 30 days. Check whether it still applies.</p></section>
            <section class="review-section"><h2>Evidence at a glance</h2><ul class="evidence-sources"><li v-for="observation in finding.observations" :key="String(observation.id)"><strong>{{ observation.source }}</strong><span class="hint">SBOM source observation</span></li><li v-for="record in finding.evidence" :key="String(record.id)"><strong>{{ record.source }}</strong><span class="hint">{{ String(record.kind || 'Additional evidence').replaceAll('-', ' ') }}</span></li></ul><p v-if="!finding.observations.length && !finding.evidence.length" class="hint">No source evidence available.</p><details :open="power"><summary>Original CVSS vectors and package coordinate</summary><p v-for="base in finding.original_vectors" :key="base.vector" class="vector-line"><strong>CVSS {{ base.version }} · {{ base.score }}</strong><code>{{ base.vector }}</code></p><code class="vector-line">{{ finding.purl || 'No PURL supplied' }}</code></details></section>
            <section v-for="(imported, index) in finding.imported_assessments" :key="index" class="review-section"><h2>Imported DT assessment</h2><p class="hint">{{ imported.source }} · {{ imported.format === 'plain-dt' ? 'Legacy documentation without DTVP metadata' : 'Previous DTVP documentation' }}. Imported history is separate from DTVP approval.</p><p v-if="imported.pending_review || imported.conflicting" class="warning">{{ imported.conflicting ? 'Imported team decisions conflict.' : 'Source assessment is pending review.' }}</p><p v-if="imported.suppressed" class="warning">Suppressed in the source. Retained for review.</p><article v-for="(record, position) in imported.current_records" :key="position"><strong>{{ record.team }} · {{ record.state ? label(record.state) : 'Applicability not recorded' }}</strong><p class="rationale-text">{{ record.rationale || 'No rationale recorded.' }}</p><small>{{ record.assessor ? `Source assessor: ${record.assessor}` : 'Assessor not recorded' }}{{ record.reviewer ? ` · Source reviewer: ${record.reviewer}` : '' }}</small><p v-if="record.rescored_score !== null" class="hint">Legacy contextual score: {{ record.rescored_score }}. Original Base severity remains unchanged.</p><p v-if="record.ssvc_priority" class="hint">Imported SSVC priority: {{ record.ssvc_priority }}</p></article></section>
            <section v-for="record in finding.evidence.filter(record => record.kind === 'contextual-assessment')" :key="String(record.id)" class="review-section"><h2>{{ record.source === 'vscorer' ? 'VScorer contextual assessment' : 'Contextual assessment' }}</h2><p v-if="typeof record.environmental_score === 'number'">Proposed Environmental score: <strong>{{ record.environmental_score.toFixed(1) }}</strong></p><p v-if="typeof record.rationale === 'string'" class="rationale-text">{{ record.rationale }}</p><p class="hint">Provider evidence requires explicit adoption and independent DTVP approval.</p></section>
          </div>
          <section v-show="step !== 0" class="assessment-column panel">
            <p v-if="!latest && !showForm" class="hint">No assessment has been submitted yet.</p><section v-if="latest && !showForm" class="assessment-summary"><h2>Latest assessment</h2><strong>{{ label(latest.state) }}</strong><p class="rationale-text">{{ latest.rationale }}</p><p class="hint">{{ latest.author_name || 'Recorded analyst' }} · {{ new Date(latest.created_at).toLocaleString() }} · {{ finding.approval && finding.lifecycle === 'approved' ? 'Reviewed and approved' : finding.lifecycle === 'needs_revalidation' ? 'Revalidation required' : 'Awaiting review' }}</p><section v-if="finding.proposed_rescoring" class="score-preview"><h3>{{ finding.adopted_rescoring ? 'Approved contextual score' : 'Proposed contextual score' }}</h3><p>CVSS {{ finding.proposed_rescoring.version }} · Original {{ finding.proposed_rescoring.base_score.toFixed(1) }} → {{ finding.proposed_rescoring.score.toFixed(1) }}</p><p class="rationale-text">{{ finding.proposed_rescoring.rationale }}</p><details><summary>Contextual vector</summary><code class="vector-line">{{ finding.proposed_rescoring.vector }}</code></details><p class="hint">Applicability and severity are separate decisions. Original Base evidence remains unchanged.</p></section></section>

            <button v-if="finding.capabilities.includes('assess') && latest && !showForm" :disabled="busy" @click="revise">Revise this assessment</button>
            <form v-if="showForm" @submit.prevent="step === lastStep && canSubmit && emit('submit', false)">
              <div v-show="step === 1"><h2>Your assessment</h2><p class="hint">Does this vulnerability apply to this release?</p><label>Applicability <select :value="draft.state" :disabled="busy" @change="update('state', ($event.target as HTMLSelectElement).value)"><option value="under_investigation">Under investigation</option><option value="affected">Affected</option><option value="not_affected">Not affected</option><option value="fixed">Fixed</option></select></label><label>Reason and evidence <textarea :value="draft.rationale" rows="5" maxlength="6000" :disabled="busy" placeholder="Record the decisive evidence and next action." @input="update('rationale', ($event.target as HTMLTextAreaElement).value)"></textarea></label><p class="hint">Draft saved in this browser session.</p></div>
              <div v-show="step === 2"><h2>Contextual severity</h2><p class="hint">Keep the original score, or adjust it for verified deployment conditions.</p><RescoreEditor :finding="finding" :state="draft.state" :model-value="draft.rescoring" :disabled="busy" :assessment-rationale="draft.rationale" @preview="scorePreview = $event" @update:model-value="value => emit('update:draft', { ...draft, rescoring: value })" /></div>
              <div v-if="step === lastStep" class="confirmation"><h2>Ready for independent review</h2><dl><dt>Applicability</dt><dd>{{ label(draft.state) }}</dd><dt>Reason and evidence</dt><dd class="rationale-text">{{ draft.rationale }}</dd><dt>Severity</dt><dd>{{ draft.rescoring ? `Original ${score(finding.original_score)} → Proposed ${scorePreview ? score(scorePreview.score) : 'Preview required'}` : `Original score ${score(finding.original_score)} retained` }}</dd></dl><p v-if="draft.rescoring" class="rationale-text">{{ draft.rescoring.rationale }}</p><p v-if="!canSubmit" class="warning">Complete the rationale and refresh the scoring preview before submitting.</p></div>
            </form>
            <div v-if="canApprove && !editing && step === lastStep" class="review-actions"><label class="score-choice"><input v-model="reviewConfirmed" type="checkbox" :disabled="busy"><span>I checked applicability, evidence and the proposed score.</span></label><p class="hint">Your approval applies to this occurrence and its current evidence.</p><div class="approval-actions"><button class="primary" :disabled="busy || !reviewConfirmed" @click="emit('approve', false, false)">Approve decision</button><button :disabled="busy || !reviewConfirmed" @click="emit('approve', false, true)">Approve and next</button><button :disabled="busy" @click="emit('approve', true, false)">Request changes</button></div></div><p v-else-if="finding.lifecycle === 'ready' && latest?.author_id === me.id" class="hint">A different reviewer must approve your assessment.</p>
          </section>
        </div>
        </div>
        <footer class="guided-footer"><button :disabled="busy || step === 0" @click="goStep(step - 1)">Back</button><span class="hint">{{ finding.identifier }}</span><button v-if="step < lastStep" class="primary" :disabled="!canContinue" @click="goStep(step + 1)">{{ step === 0 ? 'Continue to assessment' : step === 1 && showForm ? 'Continue to severity' : 'Review and confirm' }}</button><div v-else-if="showForm" class="approval-actions"><button class="primary" :disabled="!canSubmit" @click="emit('submit', false)">Submit assessment</button><button :disabled="!canSubmit" @click="emit('submit', true)">Submit and next</button></div><span v-else class="hint">{{ canApprove ? 'Confirm your review above' : 'Independent review required for changes' }}</span></footer>
      </div>
      <div v-show="tab === 'analysis'" id="review-panel-analysis" role="tabpanel" aria-labelledby="review-tab-analysis"><AnalysisPanel :key="finding.id" :finding-id="finding.id" :state-version="finding.state_version" :evidence-revision="finding.evidence_revision" :enabled="me.agentyzer.enabled" :mode="me.agentyzer.mode" :can-run="finding.capabilities.includes('evidence')" :can-assess="finding.capabilities.includes('assess')" @refresh="emit('refresh')" @proposal="useProposal" /></div>
      <div v-show="tab === 'history'" id="review-panel-history" role="tabpanel" aria-labelledby="review-tab-history"><h2>Evidence and decision history</h2><p class="hint">Full provider assertions and prior decisions remain available for detailed review.</p><section v-for="decision in finding.decisions" :key="decision.id" class="decision-record"><h3>{{ label(decision.state) }} · {{ new Date(decision.created_at).toLocaleString() }}</h3><p class="rationale-text">{{ decision.rationale }}</p><p class="hint">Evidence revision {{ decision.evidence_revision }} · {{ label(decision.status) }}</p></section><details :open="power"><summary>Technical evidence and history</summary><h3>Package coordinate</h3><code>{{ finding.purl || 'No PURL supplied' }}</code><h3>Source observations</h3><pre>{{ JSON.stringify(finding.observations, null, 2) }}</pre><h3>Contextual evidence</h3><pre>{{ JSON.stringify(finding.evidence, null, 2) }}</pre><h3>Decision history</h3><pre>{{ JSON.stringify(finding.decisions, null, 2) }}</pre></details></div>
      <div class="review-refresh"><button :disabled="busy" @click="emit('refresh')">Refresh evidence</button></div>
    </div>
  </section></div>
</template>
